insert into courses (code, slug, title, summary, phase_id, position, status, difficulty, duration_hours, topics, tools, outcomes, deliverable, is_mvp_slot) values ('M1', 'machine-learning', 'Machine Learning', 'Les principes du machine learning et leurs applications métier, sans prérequis mathématiques lourds.', 1, 1, 'coming_soon', 'beginner', 6, array['Apprentissage supervisé et non supervisé', 'Cycle de vie ML', 'Données et features', 'Évaluation des modèles', 'Applications métier']::text[], array['Navigateur', 'Notebook (optionnel)']::text[], array['Distinguer apprentissage supervisé et non supervisé sur un cas métier', 'Lire des métriques d''évaluation courantes', 'Qualifier la faisabilité d''un cas d''usage ML']::text[], 'Fiche de cadrage d''un cas d''usage ML', false);
insert into courses (code, slug, title, summary, phase_id, position, status, difficulty, duration_hours, topics, tools, outcomes, deliverable, is_mvp_slot) values ('M2', 'deep-learning', 'Deep Learning', 'Réseaux de neurones, architectures majeures et contraintes d''entraînement.', 1, 2, 'coming_soon', 'intermediate', 6, array['Réseaux de neurones', 'CNN, RNN et Transformers', 'Transfer learning', 'Contraintes d''entraînement', 'Applications multimodales']::text[], array['Navigateur']::text[], array['Expliquer le rôle des principales architectures', 'Identifier les contraintes de données et de calcul', 'Choisir entre entraînement, fine-tuning et modèle existant']::text[], 'Note de comparaison d''architectures pour un cas d''usage', false);
insert into courses (code, slug, title, summary, phase_id, position, status, difficulty, duration_hours, topics, tools, outcomes, deliverable, is_mvp_slot) values ('M3', 'ia-generative', 'IA générative', 'Modèles génératifs et LLM : fonctionnement, limites, coûts et critères de choix.', 1, 3, 'coming_soon', 'beginner', 6, array['Modèles génératifs', 'Fondamentaux des LLM', 'Tokens et fenêtres de contexte', 'Choix d''un modèle', 'Limites et coûts']::text[], array['Un assistant IA grand public']::text[], array['Expliquer tokens et fenêtre de contexte', 'Comparer des modèles selon des critères explicites', 'Identifier limites et risques d''un usage donné']::text[], 'Grille de sélection de modèle pour un usage professionnel', false);
insert into courses (code, slug, title, summary, phase_id, position, status, difficulty, duration_hours, topics, tools, outcomes, deliverable, is_mvp_slot) values ('M4', 'prompt-engineering', 'Prompt Engineering', 'Structurer, tester et évaluer des prompts fiables pour des usages professionnels.', 2, 4, 'coming_soon', 'beginner', 6, array['Structure et patterns de prompts', 'Few-shot prompting', 'Sorties structurées', 'Appel d''outils (tool calling)', 'Évaluation de prompts']::text[], array['Un assistant IA ou une API LLM']::text[], array['Concevoir un prompt structuré réutilisable', 'Obtenir des sorties structurées validables', 'Évaluer un prompt sur un jeu de cas']::text[], 'Bibliothèque de prompts évalués pour un processus métier', true);
insert into courses (code, slug, title, summary, phase_id, position, status, difficulty, duration_hours, topics, tools, outcomes, deliverable, is_mvp_slot) values ('M5', 'context-engineering', 'Context Engineering', 'Maîtriser ce que le modèle voit : gestion du contexte, mémoire, retrieval et coût en tokens.', 2, 5, 'coming_soon', 'intermediate', 6, array['Gestion de la fenêtre de contexte', 'Mémoire', 'Retrieval', 'Pertinence du contexte', 'Optimisation de la consommation de tokens']::text[], array['Un assistant IA ou une API LLM']::text[], array['Concevoir une stratégie de contexte pour un cas d''usage', 'Réduire la consommation de tokens à qualité constante', 'Choisir une stratégie de mémoire adaptée']::text[], 'Spécification de contexte pour un assistant métier', true);
insert into courses (code, slug, title, summary, phase_id, position, status, difficulty, duration_hours, topics, tools, outcomes, deliverable, is_mvp_slot) values ('M6', 'vibe-coding', 'Vibe Coding', 'Développement assisté par IA : de la spécification au produit, avec tests et maîtrise de la dette technique.', 2, 6, 'coming_soon', 'intermediate', 8, array['Développement assisté par IA', 'Claude Code', 'Cursor', 'Lovable', 'Workflows spécification → produit', 'Tests et dette technique']::text[], array['Claude Code', 'Cursor', 'Lovable']::text[], array['Transformer une spécification en prototype fonctionnel', 'Mettre en place des tests sur du code généré', 'Identifier et limiter la dette technique générée']::text[], 'Prototype fonctionnel et testé à partir d''une spécification', true);
insert into courses (code, slug, title, summary, phase_id, position, status, difficulty, duration_hours, topics, tools, outcomes, deliverable, is_mvp_slot) values ('M7', 'bmad-framework', 'BMAD Framework', 'La méthode BMad (Breakthrough Method for Agile AI-Driven Development), d''après sa documentation officielle.', 2, 7, 'coming_soon', 'intermediate', 6, array['Méthode et documentation officielles BMAD', 'Workflows de développement pilotés par agents', 'Artefacts de planification et d''implémentation', 'Cycle de développement', 'Contrôles qualité']::text[], array['Un assistant de code IA compatible']::text[], array['Appliquer le workflow BMad sur un petit projet', 'Produire les artefacts de planification attendus', 'Mettre en place des contrôles qualité']::text[], 'Dossier de planification d''un projet selon BMad', false);
insert into courses (code, slug, title, summary, phase_id, position, status, difficulty, duration_hours, topics, tools, outcomes, deliverable, is_mvp_slot) values ('M14', 'ai-ux', 'AI UX & Interaction Humain-IA', 'Concevoir des expériences IA dignes de confiance : conversation, supervision humaine, erreurs.', 2, 8, 'coming_soon', 'intermediate', 5, array['Design d''expérience conversationnelle', 'Human-in-the-loop', 'Gestion des erreurs', 'Confiance utilisateur', 'Patterns d''interfaces agentiques']::text[], array['Outil de maquettage au choix']::text[], array['Concevoir un parcours conversationnel avec reprise sur erreur', 'Définir les points de contrôle humain', 'Évaluer la confiance perçue']::text[], 'Maquette annotée d''une interaction humain-IA', false);
